import re

PATTERNS = {
    "email": r"[\w.+-]+@[\w-]+\.[\w.-]+",
    "phone": r"\b\+?\d[\d -]{7,}\d\b",
    "ssn": r"\b\d{3}-\d{2}-\d{4}\b",
    "cc": r"\b(?:\d[ -]*?){13,16}\b",
}

def redact(text: str) -> str:
    for name, pat in PATTERNS.items():
        text = re.sub(pat, f"[{name.upper()}]", text)
    return text

if __name__ == "__main__":
    print(redact("reach me at a@b.com or 555-123-4567"))
